package app.planaloud;
import android.text.InputType;import android.widget.*;import com.google.android.material.textfield.TextInputEditText;import java.net.URI;
final class VoiceOptions {
 static void show(MainActivity a){app.planaloud.voice.VoiceSettings.migrate(a);LinearLayout page=a.fullPage("语音识别",()->AiSettings.show(a));page.addView(Ui.text(a,"语音识别",22,true));page.addView(Ui.help(a,"在 AI 对话中按住麦克风录音，松开识别，上滑取消。识别文字只填回输入框，不自动发送；最长录音 120 秒。"));Spinner provider=TaskTypes.spinner(a,page,"识别服务",java.util.Arrays.asList("DeepSeek 官方 ASR","系统语音识别","阿里云百炼 Qwen-ASR"));int current=a.prefs.getInt("voice_provider",3);provider.setSelection(current==0?1:current==1?2:0);TextInputEditText ds=Ui.field(a,page,"DeepSeek API Key（留空沿用已保存的密钥）","",false);ds.setInputType(129);page.addView(Ui.help(a,"使用官方 DeepSeek 地址保存 AI 配置时，会同时配置语音密钥。系统模式直接在当前页面调用系统识别服务。"));TextInputEditText endpoint=Ui.field(a,page,"百炼 API 根地址",a.prefs.getString("voice_endpoint","https://dashscope.aliyuncs.com/compatible-mode/v1"),false),model=Ui.field(a,page,"百炼语音模型",a.prefs.getString("voice_model","qwen3-asr-flash"),false),key=Ui.field(a,page,"百炼 API Key（留空沿用已保存密钥）","",false);key.setInputType(129);
 page.addView(Ui.button(a,"保存语音设置",true,()->{try{int mode=new int[]{3,0,1}[provider.getSelectedItemPosition()];String address=endpoint.getText().toString().trim().replaceAll("/+$","");if(mode==1){URI uri=new URI(address);if(!"https".equals(uri.getScheme())||uri.getHost()==null||uri.getRawUserInfo()!=null||uri.getRawQuery()!=null||uri.getRawFragment()!=null)throw new Exception("百炼语音 API 需要完整 HTTPS 地址");if(model.length()==0)throw new Exception("请填写语音模型");}if(ds.length()>0){Secrets.put(a,"deepseek_voice_api_key",ds.getText().toString().trim());ds.setText("");}if(key.length()>0){Secrets.put(a,"voice_api_key",key.getText().toString().trim());key.setText("");}a.prefs.edit().putInt("voice_provider",mode).putString("voice_endpoint",address).putString("voice_model",model.getText().toString().trim()).apply();a.message("已保存语音设置");}catch(Exception error){a.message(error.getMessage());}}));
 }
}
